<?php if(empty($startupDetailsOnly))$startupPreview=vs_startup_preflight($configuration,!empty($_POST['tool_terms'])); ?>
<section class="startup-preflight" data-startup-preflight aria-label="Work availability">
<?php if(empty($startupDetailsOnly)): ?><p role="status"><strong><?=e(!empty($startupSummaryOnly)&&!$startupPreview['eligible']&&$startupPreview['reasons']?$startupPreview['reasons'][0]['message']:$startupPreview['summary'])?></strong></p>
<?php if(empty($startupSummaryOnly)&&$startupPreview['reasons']&&!$startupPreview['eligible']): ?><p class="fine"><?=e($startupPreview['reasons'][0]['message'])?></p><?php endif ?>
<?php endif ?>
<?php if(empty($startupSummaryOnly)): ?><details id="startup-settings" class="research-disclosure" <?=!empty($startupEditable)&&!$startupPreview['eligible']?'open':''?>><summary><?=!empty($startupEditable)?'Worker settings & availability':'Why work may be unavailable'?></summary>
<?php foreach($startupPreview['reasons'] as $reason): ?><p><strong><?=e($reason['message'])?></strong> <?=e($reason['action'])?></p><?php if(isset($reason['earliest_expiry'])): ?><p>Earliest matching reservation expiry: <?=e($reason['earliest_expiry'])?> UTC. Availability is rechecked at pickup.</p><?php endif ?><?php foreach($reason['examples'] as $blocked): ?><p><a href="<?=e($blocked['url'])?>"><?=e($blocked['title'])?></a> · <?=e($blocked['requirements'])?></p><?php endforeach ?><?php endforeach ?>
<?php if(!$startupPreview['reasons']&&!$startupPreview['eligible']): ?><p>Only currently public, approved work is checked. Pending or private requests are not listed. Check the public library or return later; do not launch an AI just to discover an empty queue.</p><?php endif ?>
<?php foreach($startupPreview['examples'] as $example): ?><p><a href="<?=e($example['url'])?>"><?=e($example['title'])?></a> · <?=e($example['kind'])?></p><?php endforeach ?>
<p class="fine">A preview reserves nothing and may change. Pickup rechecks the current task, consent, worker requirements and reservation.</p>
<?php if(!empty($startupEditable)): ?>
<form method="post" action="/volunteer"><?=csrf()?><input type="hidden" name="operation" value="configure"><input type="hidden" name="startup_edit" value="1">
<?php foreach($draft as $name=>$value): if(in_array($name,['model','reasoning','tool','workflow_mode'],true))continue; ?><input type="hidden" name="<?=e($name)?>" value="<?=e($value)?>"><?php endforeach ?>
<p>Enter the research worker’s actual configured settings, not the browser controller’s. Leave unknown settings unspecified; never guess a qualifying model or effort.</p>
<label for="startup-model">Exact worker model</label><select id="startup-model" name="model"><option value="">Not specified</option><?php foreach(wf_model_registry() as $id=>$model): ?><option value="<?=e($id)?>" <?=$configuration['capabilities']['model']===$id?'selected':''?>><?=e($model['label'])?></option><?php endforeach ?></select>
<label for="startup-effort">Actual reasoning effort</label><select id="startup-effort" name="reasoning"><option value="">Not specified</option><?php foreach(RQ_EFFORTS as $effort): ?><option value="<?=e($effort)?>" <?=$configuration['capabilities']['reasoning']===$effort?'selected':''?>><?=e(ucfirst($effort))?></option><?php endforeach ?></select>
<label for="startup-tool">Worker tool or harness</label><input id="startup-tool" name="tool" maxlength="100" value="<?=e($configuration['capabilities']['tool'])?>">
<label for="startup-mode">Worker workflow mode</label><select id="startup-mode" name="workflow_mode"><option value="">No specific mode</option><option value="ultracode" <?=$configuration['capabilities']['workflow_mode']==='ultracode'?'selected':''?>>Ultracode — separate from effort</option></select>
<p class="fine">Current planning policy: <?php foreach(wf_policy() as $entry): ?><?=e($entry['model'].': '.implode(' / ',$entry['efforts']).(in_array('ultra',$entry['efforts'],true)?' (Ultra uses '.$entry['ultra_tool'].')':'').'; ')?><?php endforeach ?> Settings remain self-reported and are checked again against the actual worker before research.</p>
<div class="actions"><button>Recheck availability</button><a class="button secondary" href="/volunteer">Change scope or limits</a></div></form>
<?php elseif(isset($configuration['id'])&&!vs_current($configuration)): ?><form method="post" action="/volunteer"><?=csrf()?><?php foreach(vs_startup_restart_input($configuration) as $name=>$value): ?><input type="hidden" name="<?=e($name)?>" value="<?=e($value)?>"><?php endforeach ?><button class="secondary">Review settings for a new session</button></form><p class="fine">Scope and limits are carried forward for your review. Existing session settings and consent remain unchanged.</p><?php endif ?>
</details><?php endif ?></section>
